  'mod.comptabilite.what' => 'खाता-चार्ट, रोज़नामचे, संतुलित प्रविष्टियाँ, खाता-बही और तलपट। एक चालान एक ही क्लिक में लेखा-प्रविष्ट हो जाता है।',
  'mod.comptabilite.caveat' => 'आंतरिक लेखा-रख-रखाव। न कर-विवरणी, न प्रेषण : तलपट का निर्यात आपके लेखाकार को जाता है।',
  'mod.paie.label' => 'वेतन इंजन',
  'mod.paie.what' => 'समायोज्य अंशदान-दरें, सकल से शुद्ध तक की गणना, नियोक्ता-अंश और नियोक्ता-लागत, विस्तृत वेतन-पर्ची।',
  'mod.paie.caveat' => 'दरें वही हैं जो आप भरते हैं : वे संकेत के तौर पर पहले से भरी होती हैं और आपके वेतन-प्रबंधक द्वारा जाँची जानी चाहिए। कोई शासकीय विवरणी नहीं बनती।',
  'mod.facturation-electronique.label' => 'इलेक्ट्रॉनिक चालान',
  'mod.facturation-electronique.what' => 'EN 16931 की अनिवार्य प्रविष्टियों की जाँच, CII XML (UN/CEFACT) और Factur-X का निर्यात : वह पठनीय PDF/A-3 जो उस XML को संलग्न रखता है।',
  'mod.facturation-electronique.caveat' => 'किसी अनुमोदित मंच पर जमा करना शेष रहता है : इसके लिए किसी संचालक के यहाँ खाता चाहिए, यहाँ की कोई सेटिंग नहीं।',
  'mod.stock.label' => 'स्टॉक और क्रय',
  'mod.stock.what' => 'वस्तुएँ, आवक-जावक गतिविधियाँ, चेतावनी-सीमा, और क्रय-अनुरोध जिन्हें पहले प्रबंधक फिर प्रबंधन स्वीकृत करता है।',
  'mod.stock.caveat' => 'एकल-गोदाम स्टॉक, अंतिम ज्ञात इकाई-मूल्य पर आँका गया। न चक्रीय गणना, न FIFO या भारित औसत मूल्यांकन।',
  'mod.tresorerie.label' => 'कोषागार',
  'mod.tresorerie.what' => 'बैंक खाते, गतिविधियाँ, प्राप्तियों का चालानों से मिलान, और बारह सप्ताह का नकदी-अनुमान।',
  'mod.tresorerie.caveat' => 'प्रविष्टि और आयात हाथ से : कोई बैंक-संपर्क (PSD2) नहीं बनता। शेष वही है जो आपने भरा, बैंक का नहीं।',
  'mod.immobilisations.label' => 'अचल संपत्तियाँ',
  'mod.immobilisations.what' => 'अचल संपत्तियों का रजिस्टर, सीधी-रेखा और ह्रासमान मूल्यह्रास तालिकाएँ, शुद्ध बही-मूल्य और वर्ष का प्रावधान।',
  'mod.immobilisations.caveat' => 'ये तालिकाएँ निगरानी का साधन हैं : लेखांकन-संबद्धता, घटक और विशेष छूटें आपके लेखाकार का विषय बनी रहती हैं।',
  'mod.crm.label' => 'विक्रय CRM',
