  'sec.wizard.againButton' => 'सहायक फिर से देखें',
  'sec.pilotage.intro' => 'संचालन वे आँकड़े जुटाता है जिन्हें प्रबंधन देखता है: कर्मचारी संख्या, कारोबार, बकाया बिल, लक्ष्य और आने वाली समय-सीमाएँ। यह कुछ भी दोबारा नहीं गिनता — जो दूसरे अनुभाग पहले से रखते हैं, उसे जोड़कर दिखाता है।',
  'sec.personnel.intro' => 'कार्मिक लोगों को सँभालता है: फ़ाइलें, अनुबंध, अवकाश, कार्यक्रम, करियर-पथ, स्वास्थ्य और सुरक्षा। इसका डेटा सबसे संवेदनशील है और यही सबसे अधिक काम आता है।',
  'sec.gestion.intro' => 'प्रबंधन पैसा और साधन सँभालता है: चालान, कोटेशन, परियोजनाएँ, वाहन-बेड़ा, भंडार, और लेखा यदि वह खुला हो।',
  'sec.relation.intro' => 'संबंध वह सब सँभालते हैं जो बाहर से और भीतर से आता है: अनुरोध, टिकट, ज्ञान-कोश, स्वागत, कार्यक्रम और समाचार।',
  'sec.technique.intro' => 'तकनीकी स्वयं प्रतिष्ठान को सँभालता है: सूचना-तंत्र, एकीकरण, अद्यतन, बैकअप, लॉग और आयात।',
  'sec.conformite.intro' => 'अनुपालन वह सँभालता है जो आपसे अपेक्षित है: खातों की सुरक्षा, डेटा-संरक्षण, विधिक कार्य और हस्ताक्षर। निरीक्षण के दिन यही अनुभाग खोला जाता है।',
  'sec.reglages.intro' => 'सेटिंग्स प्रतिष्ठान को सँभालती हैं: कंपनी की पहचान, भाषा, रूप-रंग, मॉड्यूल और अनुप्रयोग। यह अनुभाग हटाया नहीं जाता — यही दूसरों को वापस जोड़ने देता है।',
  'sec.pilotage.horizon_jours' => 'समय-सीमाओं का क्षितिज (दिन)',
  'sec.pilotage.horizon_jours.hint' => 'कोई समय-सीमा अपने अंत से इतने दिन पहले डैशबोर्ड पर आती है। कम रखें तो कम दिखेगा; अधिक रखें तो सब दिखेगा, यानी कुछ नहीं।',
