  'install.sections.lede' => 'केवल वही लें जो आपसे संबंधित है: बिना स्थापित अनुभाग कुछ नहीं दिखाता, न पट्टी में न कहीं और। कुछ भी अंतिम नहीं — एक टिक से वह लौट आता है, और उसका डेटा उसकी प्रतीक्षा करता है।',
